window.jQuery||document.writeln('<script src = "static/jquery-3.5.1.min.js">');var buttonColors=["red","blue","green","yellow"];var level=1;var generatedSequence=[];var userSeqIndx=0;var isGameEnded=true;var winningTexts=["Keep going! 🎉","Amazing!🔥","Champion vibes! 🏆","Incredible!🌟","You're unstoppable! 🚀","Fantastic! 💫","Great job! 👏","Superb! 🌈","You're a star! ⭐","Outstanding! 🥇","Bravo! 🎊","Legendary! 🐾"];var winningTextIndex=0;function cycleQuotes(){if(++winningTextIndex+1>winningTexts.length){winningTextIndex=0}return winningTexts[winningTextIndex]}function addNewColor(){generatedSequence.push(buttonColors[randomNumber()])}function randomNumber(){var random=parseInt(Math.random()*4);if(random>=4){randomException()}function randomException(){random=parseInt(Math.random()*4);if(random>=4){randomException()}}return random}async function animateSequence(){for(var i=0;i<generatedSequence.length;i++){await $("#"+generatedSequence[i]).animate({opacity:.3}).animate({opacity:1}).promise()}}async function levelHandler(){addNewColor();await animateSequence();checkSequence()}async function checkSequence(){$(".btn").on("click",(async function(event){var button=$(this);button.addClass("pressed");console.log("clicked");await button.animate({opacity:.3}).animate({opacity:1}).promise();setTimeout((function(){button.removeClass("pressed");console.log()}),200);if(userSeqIndx+1==generatedSequence.length){if(this.id!=generatedSequence[userSeqIndx++]){gameLost();return false}setTimeout((function(){nextLevel()}),1e3)}else if(userSeqIndx<generatedSequence.length){if(this.id!=generatedSequence[userSeqIndx++]){gameLost();return false}}else{setTimeout((function(){nextLevel()}),1e3)}function gameLost(){$("#level-title").text("Aw cutie, you lost! Wanna marry me?💐 Press A.");isGameEnded=true;$(".btn").off("click")}function nextLevel(){$("#level-title").text(winningTexts[randomNumber()]);level++;userSeqIndx=0;levelHandler();$(".btn").off("click")}}))}function startGame(){level=1;isGameEnded=false;levelHandler()}$(document).on("click",(function(){if(isGameEnded){startGame();$("#level-title").text("Game On!")}}));$(document).on("keydown",(function(event){if(event.key.toLowerCase()=="a"&&isGameEnded){startGame();$("#level-title").text("Game On!")}}));